//! 🕰️ Immutable segmented history and bounded physical reconciliation.

use super::*;
#[path="🧭️decision/🦀️.rs"]
pub(crate) mod decision;
const CONTAINER:&str="segments";
const MAXIMUM_SEGMENTS:usize=4096;
const ORDINARY_NAMES:usize=4080;
const ORDINARY_BYTES:u64=66_060_288;
const PAGE:usize=64;
